<script lang="ts">
  interface Props {
    src?: any,
    size?: string | number,
    mini?: boolean
    micro?: boolean
    solid?: boolean
    variant?: string | null
    class?: string
    style?: string
  }

  let {
    src,
    size = '24',
    mini = false,
    micro = false,
    solid = false,
    variant = null,
    class: className,
    style = '',
    ...rest
  }: Props = $props()

  let selectedVariant =
    variant || (micro ? 'micro' : mini ? 'mini' : solid ? 'solid' : 'outline')

  let icon = $derived(src?.[selectedVariant] || src?.outline || {})

  let svgAttributes = icon
    ? {
        ...icon.a,
        ...(className && { class: className }),
        ...(style && { style }),
      }
    : {}
</script>

<svg
  {...svgAttributes}
  xmlns="http://www.w3.org/2000/svg"
  width={size}
  height={size}
  aria-hidden="true"
  {...rest}
>
  {#each icon?.path ?? [] as a}
    <path {...a} />
  {/each}
</svg>
